77	func TestRegisterArtifactCreated(t *testing.T) {
78		router, _ := newTestRouter(t)
79	
80		recorder := postArtifact(t, router, validRegistration(testDigestA))
81		if recorder.Code != http.StatusCreated {
82			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusCreated, recorder.Body)
83		}
84		body := decodeBody(t, recorder)
85		want := map[string]any{
86			"repository":         "team/app",
87			"digest":             testDigestA,
88			"tag":                "latest",
89			"signature_verified": true,
90			"retention_days":     float64(30),
91			"size_bytes":         float64(1024),
92		}
93		for key, value := range want {
94			if body[key] != value {
95				t.Fatalf("field %s = %v, want %v", key, body[key], value)
96			}
97		}
98		pushedAt, ok := body["pushed_at"].(string)
99		if !ok {
100			t.Fatalf("pushed_at missing or not a string: %v", body)
101		}
102		parsed, err := time.Parse(time.RFC3339, pushedAt)
103		if err != nil {
104			t.Fatalf("pushed_at %q is not RFC3339: %v", pushedAt, err)
105		}
106		if parsed.Location() != time.UTC {
107			t.Fatalf("pushed_at %q is not UTC", pushedAt)
108		}
109	}
110	
111	func TestRegisterArtifactNormalizesAndIgnoresUnknownFields(t *testing.T) {
112		router, _ := newTestRouter(t)
113	
114		recorder := postArtifact(t, router, `{"repository":"  team/app  ","digest":"`+testDigestA+`",`+
115			`"tag":"  latest ","signature_verified":false,"retention_days":1,"size_bytes":0,"extra":"ignored"}`)
116		if recorder.Code != http.StatusCreated {
117			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusCreated, recorder.Body)
118		}
119		body := decodeBody(t, recorder)
120		if body["repository"] != "team/app" || body["tag"] != "latest" {
121			t.Fatalf("values were not trimmed: %v", body)
122		}
123	}
124	
125	func TestRegisterArtifactRejectsInvalidInput(t *testing.T) {
126		cases := map[string]string{
127			"empty body":            ``,
128			"json array":            `[{"repository":"team/app"}]`,
129			"json scalar":           `"text"`,
130			"json null":             `null`,
131			"trailing object":       validRegistration(testDigestA) + ` {}`,
132			"malformed json":        `{"repository":`,
133			"missing repository":    `{"digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
134			"missing digest":        `{"repository":"team/app","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
135			"missing tag":           `{"repository":"team/app","digest":"` + testDigestA + `","signature_verified":true,"retention_days":30,"size_bytes":1}`,
136			"missing signature":     `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","retention_days":30,"size_bytes":1}`,
137			"missing retention":     `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"size_bytes":1}`,
138			"missing size":          `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30}`,
139			"blank repository":      `{"repository":"   ","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
140			"blank tag":             `{"repository":"team/app","digest":"` + testDigestA + `","tag":"  ","signature_verified":true,"retention_days":30,"size_bytes":1}`,
141			"repository wrong type": `{"repository":7,"digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
142			"digest wrong prefix":   `{"repository":"team/app","digest":"sha512:` + strings.Repeat("a", 64) + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
143			"digest uppercase hex":  `{"repository":"team/app","digest":"sha256:` + strings.Repeat("A", 64) + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
144			"digest too short":      `{"repository":"team/app","digest":"sha256:` + strings.Repeat("a", 63) + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1}`,
145			"signature not bool":    `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":"true","retention_days":30,"size_bytes":1}`,
146			"retention zero":        `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":0,"size_bytes":1}`,
147			"retention too large":   `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":3651,"size_bytes":1}`,
148			"retention fractional":  `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":1.5,"size_bytes":1}`,
149			"retention as string":   `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":"30","size_bytes":1}`,
150			"size negative":         `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":-1}`,
151			"size fractional":       `{"repository":"team/app","digest":"` + testDigestA + `","tag":"latest","signature_verified":true,"retention_days":30,"size_bytes":1.5}`,
152		}
153		for name, body := range cases {
154			t.Run(name, func(t *testing.T) {
155				router, _ := newTestRouter(t)
156				recorder := postArtifact(t, router, body)
157				if recorder.Code != http.StatusBadRequest {
158					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusBadRequest, recorder.Body)
159				}
160				if code := errorCode(t, recorder); code != codeInvalidInput {
161					t.Fatalf("error code = %q, want %q", code, codeInvalidInput)
162				}
163				// A rejected registration must leave no record behind.
164				lookup := getArtifacts(t, router, "repository=team/app")
165				if lookup.Code != http.StatusNotFound {
166					t.Fatalf("after rejection, list status = %d, want %d", lookup.Code, http.StatusNotFound)
167				}
168			})
169		}
170	}
171	
172	func TestRegisterDuplicateReturnsOriginalRecord(t *testing.T) {
173		router, _ := newTestRouter(t)
174	
175		first := postArtifact(t, router, validRegistration(testDigestA))
176		if first.Code != http.StatusCreated {
177			t.Fatalf("first status = %d", first.Code)
178		}
179		firstPushedAt := decodeBody(t, first)["pushed_at"]
180	
181		// Same content after normalization (extra whitespace, unknown field).
182		second := postArtifact(t, router, `{"repository":" team/app ","digest":"`+testDigestA+`","tag":"latest",`+
183			`"signature_verified":true,"retention_days":30,"size_bytes":1024,"unknown":1}`)
184		if second.Code != http.StatusCreated {
185			t.Fatalf("duplicate status = %d, want %d (%s)", second.Code, http.StatusCreated, second.Body)
186		}
187		if got := decodeBody(t, second)["pushed_at"]; got != firstPushedAt {
188			t.Fatalf("pushed_at changed on duplicate: %v -> %v", firstPushedAt, got)
189		}
190	}
191	
192	func TestRegisterConflictOnDifferentContent(t *testing.T) {
193		router, _ := newTestRouter(t)
194		postArtifact(t, router, validRegistration(testDigestA))
195	
196		recorder := postArtifact(t, router, `{"repository":"team/app","digest":"`+testDigestA+`","tag":"other",`+
197			`"signature_verified":true,"retention_days":30,"size_bytes":1024}`)
198		if recorder.Code != http.StatusConflict {
199			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusConflict, recorder.Body)
200		}
201		if code := errorCode(t, recorder); code != codeConflict {
202			t.Fatalf("error code = %q, want %q", code, codeConflict)
203		}
204	}
205	
206	func TestTagPointerMovesToNewDigestAndOldRecordSurvives(t *testing.T) {
207		router, _ := newTestRouter(t)
208		postArtifact(t, router, validRegistration(testDigestA))
209		postArtifact(t, router, validRegistration(testDigestB))
210	
211		// The tag now resolves to the new record.
212		recorder := getArtifacts(t, router, "repository=team/app&tag=latest")
213		if recorder.Code != http.StatusOK {
214			t.Fatalf("tag query status = %d (%s)", recorder.Code, recorder.Body)
215		}
216		artifacts := decodeBody(t, recorder)["artifacts"].([]any)
217		if len(artifacts) != 1 || artifacts[0].(map[string]any)["digest"] != testDigestB {
218			t.Fatalf("tag does not point at new record: %v", artifacts)
219		}
220	
221		// The old record is still queryable by digest.
222		recorder = getArtifacts(t, router, "repository=team/app&digest="+testDigestA)
223		if recorder.Code != http.StatusOK {
224			t.Fatalf("digest query status = %d (%s)", recorder.Code, recorder.Body)
225		}
226	
227		// Retrying the old registration succeeds but must not move the tag back.
228		retry := postArtifact(t, router, validRegistration(testDigestA))
229		if retry.Code != http.StatusCreated {
230			t.Fatalf("retry status = %d (%s)", retry.Code, retry.Body)
231		}
232		recorder = getArtifacts(t, router, "repository=team/app&tag=latest")
233		artifacts = decodeBody(t, recorder)["artifacts"].([]any)
234		if artifacts[0].(map[string]any)["digest"] != testDigestB {
235			t.Fatalf("retry moved the tag pointer: %v", artifacts)
236		}
237	}
238	
239	func TestListArtifactsInRegistrationOrder(t *testing.T) {
240		router, _ := newTestRouter(t)
241		postArtifact(t, router, validRegistration(testDigestB))
242		postArtifact(t, router, validRegistration(testDigestA))
243	
244		recorder := getArtifacts(t, router, "repository=team/app")
245		if recorder.Code != http.StatusOK {
246			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body)
247		}
248		artifacts := decodeBody(t, recorder)["artifacts"].([]any)
249		if len(artifacts) != 2 {
250			t.Fatalf("got %d artifacts, want 2", len(artifacts))
251		}
252		if artifacts[0].(map[string]any)["digest"] != testDigestB ||
253			artifacts[1].(map[string]any)["digest"] != testDigestA {
254			t.Fatalf("records not in registration order: %v", artifacts)
255		}
256	}
257	
258	func TestQueryValidation(t *testing.T) {
259		router, _ := newTestRouter(t)
260		postArtifact(t, router, validRegistration(testDigestA))
261	
262		for name, query := range map[string]string{
263			"missing repository":   "tag=latest",
264			"blank repository":     "repository=%20%20",
265			"tag and digest":       "repository=team/app&tag=latest&digest=" + testDigestA,
266			"blank tag":            "repository=team/app&tag=%20",
267			"malformed digest":     "repository=team/app&digest=sha256:xyz",
268			"uppercase repository": "repository=TEAM/APP&tag=latest", // case-sensitive: valid but no match
269		} {
270			t.Run(name, func(t *testing.T) {
271				recorder := getArtifacts(t, router, query)
272				if name == "uppercase repository" {
273					if recorder.Code != http.StatusNotFound {
274						t.Fatalf("status = %d, want %d", recorder.Code, http.StatusNotFound)
275					}
276					return
277				}
278				if recorder.Code != http.StatusBadRequest {
279					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusBadRequest, recorder.Body)
280				}
281				if code := errorCode(t, recorder); code != codeInvalidInput {
282					t.Fatalf("error code = %q, want %q", code, codeInvalidInput)
283				}
284			})
285		}
286	}
287	
288	func TestQueryNotFound(t *testing.T) {
289		router, _ := newTestRouter(t)
290		postArtifact(t, router, validRegistration(testDigestA))
291	
292		for name, query := range map[string]string{
293			"unknown repository": "repository=other/repo",
294			"unknown tag":        "repository=team/app&tag=missing",
295			"unknown digest":     "repository=team/app&digest=" + testDigestB,
296		} {
297			t.Run(name, func(t *testing.T) {
298				recorder := getArtifacts(t, router, query)
299				if recorder.Code != http.StatusNotFound {
300					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusNotFound, recorder.Body)
301				}
302				if code := errorCode(t, recorder); code != codeNotFound {
303					t.Fatalf("error code = %q, want %q", code, codeNotFound)
304				}
305			})
306		}
307	}
308	
309	func TestRecordsSurviveRestart(t *testing.T) {
310		router, path := newTestRouter(t)
311		first := postArtifact(t, router, validRegistration(testDigestA))
312		pushedAt := decodeBody(t, first)["pushed_at"]
313	
314		// Reopen the same database file behind a fresh router.
315		reopened, err := store.Open(path)
316		if err != nil {
317			t.Fatalf("reopen: %v", err)
318		}
319		defer reopened.Close()
320		router = NewRouter(reopened)
321	
322		recorder := getArtifacts(t, router, "repository=team/app&tag=latest")
323		if recorder.Code != http.StatusOK {
324			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body)
325		}
326		artifacts := decodeBody(t, recorder)["artifacts"].([]any)
327		record := artifacts[0].(map[string]any)
328		if record["digest"] != testDigestA || record["pushed_at"] != pushedAt {
329			t.Fatalf("record did not survive restart: %v", record)
330		}
331	}
